<template><section class="wrf-ui wrf-run"><header class="wrf-head"><div><small>WRF RUN</small><h2>{{task?.id||'任务运行'}}</h2></div><span>{{status}}</span></header><template v-if="task"><div class="wrf-progress"><div><b>{{runStageLabel(progress.stage)}}</b><span>{{progress.label}}</span></div><progress v-if="progress.percent!==null" max="100" :value="progress.percent"></progress><p v-else class="wrf-muted">{{progress.hint}}</p></div><dl class="wrf-summary"><div><dt>驱动资料</dt><dd>{{String(task.request?.data_source||'gfs').toUpperCase()}}</dd></div><div><dt>模拟时段（UTC）</dt><dd>{{task.request?.start_time}} → {{task.request?.end_time}}</dd></div><div><dt>已观测模拟时间（UTC）</dt><dd>{{progress.modelTime||'尚未观测到 WRF 模拟时间'}}</dd></div><div><dt>计算域</dt><dd>{{task.request?.domains?.length||0}} 个</dd></div><div><dt>Spin-up / 垂直层</dt><dd>{{task.request?.spinup?.hours??task.runtime?.spinup_hours??'—'}} h / {{verticalLevels===null?'未记录':verticalLevels+' 层'}}</dd></div></dl><p v-if="task.status==='queued'" role="status" class="wrf-muted">{{task.runtime?.resource_wait_reason||'已受理，等待调度；尚未开始积分'}}</p><p v-if="failure" role="alert" class="wrf-error">{{failure.summary}}</p><details v-if="failure?.details" class="wrf-logs wrf-technical"><summary>技术详情</summary><pre>{{failure.details}}</pre></details><div class="wrf-actions"><button v-if="allowed('back')" @click="emit('action',{action:'back'})">返回配置</button><button v-if="!terminal&&allowed('cancel')" :disabled="disabled||task.status==='cancel_pending'" @click="emit('action',{action:'cancel'})">取消任务</button><button v-if="allowed('result')&&['succeeded','partial_success'].includes(task.status)" class="primary" @click="emit('action',{action:'result'})">查看结果</button><button v-if="terminal&&allowed('reuse')" @click="emit('action',{action:'reuse'})">复用参数新建</button><button v-if="allowed('refresh')" @click="emit('action',{action:'refresh'})">刷新状态</button></div><div v-if="hostMode!=='agent'" class="wrf-actions"><button v-if="primaryOperation" :disabled="disabled" @click="emit('action',{action:primaryOperation.action})">{{operationLabels[primaryOperation.action]}}</button><details class="wrf-operation-menu"><summary>更多操作</summary><div class="wrf-actions"><button v-for="operation in secondaryOperations" :key="operation.action" :disabled="disabled||!operation.enabled" :title="operation.reason||''" @click="emit('action',{action:operation.action})">{{operationLabels[operation.action]||operation.action}}</button><button v-if="task.operations?.some(o=>o.action==='restart'&&o.enabled)" :disabled="disabled" @click="emit('action',{action:'edit-restart'})">修改后重跑</button></div><p v-for="operation in secondaryOperations.filter(o=>!o.enabled)" :key="operation.action" class="wrf-muted">{{operationLabels[operation.action]}}：{{operation.reason}}</p></details></div><div v-if="task.attempts?.length&&hostMode!=='agent'" class="wrf-actions"><label>运行尝试 <select aria-label="运行尝试" :value="logAttemptNo||task.attempt_no" @change="emit('action',{action:'attempt-change',attemptNo:Number($event.target.value)})"><option v-for="item in task.attempts" :key="item.attempt_no" :value="item.attempt_no">第 {{item.attempt_no}} 次 · {{runStatusLabel(item.status)}}</option></select></label><details v-if="historyAttempt?.request"><summary>所选尝试参数</summary><pre>{{JSON.stringify(historyAttempt.request,null,2)}}</pre></details></div><details class="wrf-logs"><summary>运行日志 · 第 {{logAttemptNo||task.attempt_no||1}} 次尝试</summary><pre>{{logs||'等待任务日志…'}}</pre></details></template><p v-else>请选择任务。</p></section></template>
<script setup>
import {computed} from 'vue';
import {runFailure} from './runFailure.js';
import {runProgress,runStageLabel,runStatusLabel} from './runLabels.js';
const props=defineProps({task:Object,logs:String,logAttemptNo:Number,disabled:Boolean,hostMode:String,allowedActions:Array});const emit=defineEmits(['action']);
const allowed=action=>props.allowedActions?props.allowedActions.includes(action):props.hostMode==='agent'?['refresh','result'].includes(action):true;
const operationLabels={resume:'恢复连接并核验状态',retry_outputs:'重试结果处理',render_partial:'部分渲染',restart:'原参数重跑',publish:'重试发布'};
const primaryOperation=computed(()=>(props.task?.operations||[]).find(o=>o.enabled&&o.action!=='cancel'));
const secondaryOperations=computed(()=>(props.task?.operations||[]).filter(o=>o.action!=='cancel'&&o.action!==primaryOperation.value?.action));
const historyAttempt=computed(()=>props.task?.attempts?.find(a=>a.attempt_no===(props.logAttemptNo||props.task.attempt_no)));
const terminal=computed(()=>['succeeded','partial_success','failed','cancelled','waiting_restart'].includes(props.task?.status));
const progress=computed(()=>runProgress(props.task));
const status=computed(()=>props.task?.status==='waiting_restart'?(props.task?.stage==='failed'?'失败·待处理':'状态待核验'):runStatusLabel(props.task?.status));
const verticalLevels=computed(()=>{const request=props.task?.request||{};const levels=request.vertical_levels??request.namelist?.input?.domains?.e_vert??props.task?.runtime?.vertical_levels;const values=Array.isArray(levels)?levels:[levels];return values.length&&values.every(v=>Number.isInteger(v)&&v>0&&v===values[0])?values[0]:null;});
const failure=computed(()=>runFailure(props.task));
</script>
